  'report.title': 'Configuración de informes', 'report.subtitle': 'Diagnósticos locales privados y consentimiento',
  'report.automatic': 'Informes de diagnóstico automáticos',
  'report.destination': 'Los informes de diagnóstico se envían a https://gamja.top/api/gamja-bot/reports cuando el servicio verificado está disponible. El envío no está disponible en esta compilación si no se ha configurado el receptor.',
  'report.contents': 'Los informes contienen la versión de la aplicación y la compilación, el sistema operativo y la arquitectura, la hora, el componente, la etapa, el código de error fijo, el número de incidencias y hasta 16 transiciones fijas. Un fallo con un diagnóstico depurado también incluye un ID de correlación, una razón y clase de excepción fijas, marcos de pila relativos a la aplicación, ID de contexto limitados, estado HTTP y un ID de solicitud del proveedor validado. No contienen chats, instrucciones de agentes, texto del proveedor, claves, URL, rutas de inicio, salida de procesos, portapapeles, contenido del navegador, capturas de pantalla, registros sin procesar ni cuerpos de solicitudes o respuestas. La descripción manual opcional se trata por separado y se muestra antes del envío.',
  'report.retention': 'Los informes locales no enviados caducan a los 7 días. El receptor conserva los informes aceptados durante 30 días. Antes de habilitar el envío en vivo, se requiere un aviso de privacidad publicado y un procedimiento de acceso para operadores.',
  'report.consent': 'Esta opción se aplica a esta instalación en tu perfil de usuario del sistema operativo durante esta sesión de la aplicación. Solo cubre los fallos nuevos posteriores a su activación. Tras reiniciar la aplicación, los informes automáticos comienzan desactivados; actívalos de nuevo para esa sesión. Al desactivarlos, se detienen los reintentos automáticos posteriores y se eliminan los informes automáticos no enviados. Este control no puede retirar un informe ya recibido.',
  'report.autoSend': 'Enviar errores de diagnóstico automáticamente', 'report.loading': 'Cargando la configuración local de informes…',
  'report.unavailable': 'Envío no disponible. La activación automática estará disponible cuando se configure el receptor verificado.',
  'report.localCount': { one: '{count} informe local', other: '{count} informes locales' },
  'report.entryCount': { one: '{count} entrada de diagnóstico', other: '{count} entradas de diagnóstico' },
