  'problem.privacy': 'Solo se envían los campos mostrados en la vista previa completa del informe. Los fallos seleccionados pueden incluir un ID de correlación, una razón y clase de excepción fijas, marcos de pila relativos a la aplicación, ID de contexto limitados, estado HTTP y un ID de solicitud del proveedor validado. No se recopilan chats, claves, capturas de pantalla, registros sin procesar, rutas locales, cuerpos de solicitudes o respuestas ni archivos. El texto que escribas puede contener información personal.',
