  "localModels.previous.title": "Configuraciones locales anteriores",
  "localModels.previous.scope": "Muestra solo intentos e informes conservados en esta sesión. La configuración anterior más reciente y los intentos pendientes o inciertos siguen visibles. El filtro de estado del archivo indica el resultado de guardar la conexión, no el de probar funciones. Leer un informe antiguo no restaura entradas, crea conexiones, ejecuta pruebas ni cambia funciones disponibles.",
